package com.evidencevault.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="cases",indexes=@Index(name="idx_case_status",columnList="status"))
public class InvestigationCase { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="case_id",nullable=false,unique=true,length=30) private String caseId; @Column(nullable=false,length=200) private String title; @Column(columnDefinition="TEXT") private String description; @Column(nullable=false,length=50) private String investigationType; @Column(nullable=false,length=30) private String status="OPEN"; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="created_by") private User createdBy; private LocalDateTime createdAt; private LocalDateTime updatedAt;
 @PrePersist void pre(){createdAt=LocalDateTime.now();updatedAt=createdAt;} @PreUpdate void upd(){updatedAt=LocalDateTime.now();}
 public Long getId(){return id;} public String getCaseId(){return caseId;} public void setCaseId(String v){caseId=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getInvestigationType(){return investigationType;} public void setInvestigationType(String v){investigationType=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public User getCreatedBy(){return createdBy;} public void setCreatedBy(User v){createdBy=v;} public LocalDateTime getCreatedAt(){return createdAt;} public LocalDateTime getUpdatedAt(){return updatedAt;} }
